/// Three dependent loads: block, leaf, class id, then one table read for
/// every General_Category and derived-boolean fact at once.
pub fn generalCategoryProperties(cp: u21) GeneralCategoryProperties {
    if (cp >= 0x110000) return class_default;
    const mid = gc_stage1[cp >> gc_s1];
    const leaf = gc_stage2[(@as(usize, mid) << (gc_s1 - gc_s2)) | (cp >> gc_s2 & ((1 << (gc_s1 - gc_s2)) - 1))];
    const id = gc_stage3[@as(usize, leaf) | (cp & ((1 << gc_s2) - 1))];
    return class_table[id];
}

pub fn generalCategory(cp: u21) GeneralCategory {
    return generalCategoryProperties(cp).category;
}

pub fn is_alphabetic(cp: u21) bool { return generalCategoryProperties(cp).is_alphabetic; }
